#include <stdlib.h>

int main() {
    int L, C;
    scanf("%d %d", &L, &C);

    int *prev = (int*)malloc(C * sizeof(int));
    int *curr = (int*)malloc(C * sizeof(int));
    int m = C - 1;

    int *heights = (int*)calloc(m, sizeof(int));
    int *stack = (int*)malloc((m + 1) * sizeof(int));

    int ans = (L > C) ? L : C;

    for (int j = 0; j < C; j++) {
        scanf("%d", &prev[j]);
    }

    for (int i = 1; i < L; i++) {
        for (int j = 0; j < C; j++) {
            scanf("%d", &curr[j]);
        }

        for (int j = 0; j < m; j++) {
            if (prev[j] + curr[j + 1] <= prev[j + 1] + curr[j]) {
                heights[j]++;
            } else {
                heights[j] = 0;
            }
        }

        int top = 0;
        for (int j = 0; j <= m; j++) {
            int h = (j < m) ? heights[j] : 0;
            while (top > 0 && heights[stack[top - 1]] > h) {
                int height = heights[stack[--top]];
                int left = (top > 0) ? stack[top - 1] : -1;
                int right = j;
                int width = right - left - 1;
                int area = (height + 1) * (width + 1);
                if (area > ans) ans = area;
            }
            if (j < m) {
                stack[top++] = j;
            }
        }

        int *tmp = prev;
        prev = curr;
        curr = tmp;
    }

    printf("%d\n", ans);

    free(prev);
    free(curr);
    free(heights);
    free(stack);

    return 0;
}
