int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    int *A = (int*)malloc((size_t)L * C * sizeof(int));
    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < C; ++j) {
            scanf("%d", &A[i * C + j]);
        }
    }

    int M = C - 1;
    int *height = (int*)calloc(M, sizeof(int));
    int *stH = (int*)malloc((M + 1) * sizeof(int));
    int *stStart = (int*)malloc((M + 1) * sizeof(int));

    long long ans = (L > C) ? L : C;

    for (int i = 0; i < L - 1; ++i) {
        int *row0 = A + (size_t)i * C;
        int *row1 = A + (size_t)(i + 1) * C;

        for (int j = 0; j < M; ++j) {
            long long lhs = (long long)row0[j] + row1[j + 1];
            long long rhs = (long long)row0[j + 1] + row1[j];
            if (lhs <= rhs) {
                ++height[j];
            } else {
                height[j] = 0;
            }
        }

        int top = -1;
        for (int j = 0; j <= M; ++j) {
            int cur = (j < M) ? height[j] : 0;
            int start = j;

            while (top >= 0 && stH[top] > cur) {
                int h = stH[top];
                int s = stStart[top--];
                int w = j - s;

                if (h > 0) {
                    long long val = (long long)(h + 1) * (w + 1);
                    if (val > ans) ans = val;
                }
                start = s;
            }

            if (top < 0 || stH[top] < cur) {
                stH[++top] = cur;
                stStart[top] = start;
            }
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(height);
    free(stH);
    free(stStart);
    return 0;
}
